fn walk_stmt<'a, State, T: ?Sized + Traverse<'a, State>>(
    node: Stmt,
    traverser: &mut T,
    ctx: &mut TraverseCtx<'_, 'a, State>,
) {
    let kind = unsafe { *ctx.ast.nodes.kind_unchecked(node.0) };
    match kind {
        NodeKind::BlockStatement => {
            walk_block_statement(BlockStatement(node.0), traverser, ctx);
        }
        NodeKind::BreakStatement => {
            walk_break_statement(BreakStatement(node.0), traverser, ctx);
        }
        NodeKind::ContinueStatement => {
            walk_continue_statement(ContinueStatement(node.0), traverser, ctx);
        }
        NodeKind::DebuggerStatement => {
            walk_debugger_statement(DebuggerStatement(node.0), traverser, ctx);
        }
        NodeKind::DoWhileStatement => {
            walk_do_while_statement(DoWhileStatement(node.0), traverser, ctx);
        }
        NodeKind::EmptyStatement => {
            walk_empty_statement(EmptyStatement(node.0), traverser, ctx);
        }
        NodeKind::ExpressionStatement => {
            walk_expression_statement(ExpressionStatement(node.0), traverser, ctx);
        }
        NodeKind::ForInStatement => {
            walk_for_in_statement(ForInStatement(node.0), traverser, ctx);
        }
        NodeKind::ForOfStatement => {
            walk_for_of_statement(ForOfStatement(node.0), traverser, ctx);
        }
        NodeKind::ForStatement => {
            walk_for_statement(ForStatement(node.0), traverser, ctx);
        }
        NodeKind::IfStatement => {
            walk_if_statement(IfStatement(node.0), traverser, ctx);
        }
        NodeKind::LabeledStatement => {
            walk_labeled_statement(LabeledStatement(node.0), traverser, ctx);
        }
        NodeKind::ReturnStatement => {
            walk_return_statement(ReturnStatement(node.0), traverser, ctx);
        }
        NodeKind::SwitchStatement => {
            walk_switch_statement(SwitchStatement(node.0), traverser, ctx);
        }
        NodeKind::ThrowStatement => {
            walk_throw_statement(ThrowStatement(node.0), traverser, ctx);
        }
        NodeKind::TryStatement => {
            walk_try_statement(TryStatement(node.0), traverser, ctx);
        }
        NodeKind::WhileStatement => {
            walk_while_statement(WhileStatement(node.0), traverser, ctx);
        }
        NodeKind::WithStatement => {
            walk_with_statement(WithStatement(node.0), traverser, ctx);
        }
        NodeKind::VariableDeclaration
        | NodeKind::Function
        | NodeKind::Class
        | NodeKind::TsFunction
        | NodeKind::TsTypeAliasDeclaration
        | NodeKind::TsInterfaceDeclaration
        | NodeKind::TsEnumDeclaration
        | NodeKind::TsModuleDeclaration
        | NodeKind::TsGlobalDeclaration
        | NodeKind::TsImportEqualsDeclaration => {
            traverser.enter_decl(Decl(node.0), ctx);
            walk_decl(Decl(node.0), traverser, ctx);
            traverser.exit_decl(Decl(node.0), ctx);
        }
        NodeKind::ImportDeclaration => {
            walk_import_declaration(ImportDeclaration(node.0), traverser, ctx);
        }
        NodeKind::ExportNamedDeclaration => {
            walk_export_named_declaration(ExportNamedDeclaration(node.0), traverser, ctx);
        }
        NodeKind::ExportDefaultDeclaration => {
            walk_export_default_declaration(ExportDefaultDeclaration(node.0), traverser, ctx);
        }
        NodeKind::ExportAllDeclaration => {
            walk_export_all_declaration(ExportAllDeclaration(node.0), traverser, ctx);
        }
        NodeKind::TsExportAssignment => {
            walk_ts_export_assignment(TsExportAssignment(node.0), traverser, ctx);
        }
        NodeKind::TsNamespaceExportDeclaration => {
            walk_ts_namespace_export_declaration(
                TsNamespaceExportDeclaration(node.0),
                traverser,
                ctx,
            );
        }
        _ => unsafe { std::hint::unreachable_unchecked() },
    }
}
